import { useMutation, useQuery } from 'urql';

// Generated by codegen at install, with no configuration in the package: every
// .graphql file of the package is its documents.
import { MissingDocument, PreferencesDocument, ShippingZonesDocument, ToggleSmtpDocument } from './gql/graphql';

export const SettingsPage = () => {
  const [preferences] = useQuery({ query: PreferencesDocument });
  const [zones] = useQuery({ query: ShippingZonesDocument });
  const [, toggle] = useMutation(ToggleSmtpDocument);
  const [missing] = useQuery({ query: MissingDocument });
  return (
    <button onClick={() => void toggle({ enabled: !preferences.data?.preferences.smtpEnabled })}>
      {zones.data?.shippingZones.length ?? 0} {missing.fetching ? '' : 'smtp'}
    </button>
  );
};
